def is_increasing_date(date_str):
    # Split the date string into components
    parts = date_str.split('/')

    # Check if the date has exactly three parts
    if len(parts) != 3:
        return "Invalid date"

    day, month, year = parts

    # Validate the day, month, and year formats
    if not (day.isdigit() and month.isdigit() and year.isdigit()):
        return "Invalid date"

    if len(day) != 2 or len(month) != 2 or len(year) != 4:
        return "Invalid date"

    if not (1 <= int(day) <= 31) or not (1 <= int(month) <= 12) or not (1000 <= int(year) <= 9999):
        return "Invalid date"

    # Convert to integers for comparison
    day = int(day)
    month = int(month)
    year = int(year)

    # Check if the date is increasing
    if day <= month <= year:
        return "Yes"
    else:
        return "No"

# Test cases
print(is_increasing_date("01/02/2003"))  # Yes
print(is_increasing_date("05/04/2020"))  # No
print(is_increasing_date("31/12/2025"))  # No
print(is_increasing_date("99/99/9999"))  # Invalid date
"
        }
